    // TABLE LOGIC
    function initTable() {
      const tbody = document.getElementById('table-body');
      let html = '';
      items.forEach((item, i) => {
        html += `<tr class="table-row" id="tr-${i}">
          <td class="td-num"><b>${i+1}</b></td>
          <td><span class="td-badge">[${item.badge}]</span><br><span class="td-kw">${item.kw}</span></td>
          <td class="td-q">${item.q}</td>
          <td class="td-ans">${item.ans}</td>
        </tr>`;
      });
      tbody.innerHTML = html;
      updateTablePagination();
    }

    function updateTablePagination() {
      for(let i=0; i<items.length; i++) {
        const tr = document.getElementById(`tr-${i}`);
        if(i >= tablePage * itemsPerPage && i < (tablePage + 1) * itemsPerPage) {
          tr.classList.add('active-page');
        } else {
          tr.classList.remove('active-page');
        }
      }
      document.getElementById('t-page').innerText = `페이지 ${tablePage + 1} / ${totalPages}`;
    }

    function goNextPage() {
      if(tablePage < totalPages - 1) {
        tablePage++;
        updateTablePagination();
        window.scrollTo(0, 0);
      }
    }

    function goPrevPage() {
      if(tablePage > 0) {
        tablePage--;
        updateTablePagination();
        window.scrollTo(0, 0);
      }
    }

    // REWARD LOGIC
    
    function handleSRS(level) {
      // Save interval data
      const now = new Date().getTime();
      let addMs = 0;
      if (level === 'again') addMs = 5 * 60 * 1000;
      if (level === 'hard') addMs = 1 * 24 * 60 * 60 * 1000;
      if (level === 'good') addMs = 5 * 24 * 60 * 60 * 1000;
      if (level === 'easy') addMs = 7 * 24 * 60 * 60 * 1000;
      
      let srsData = JSON.parse(localStorage.getItem('kice_srs') || '{}');
      if (items[currentIndex]) {
        srsData[items[currentIndex].kw] = now + addMs;
        localStorage.setItem('kice_srs', JSON.stringify(srsData));
      }
      
      // Trigger appropriate reward UI and audio
      if (level === 'again' || level === 'hard') {
        showRewardUI('wrong');
      } else {
        showRewardUI('right');
      }
      updateDashboard();
      localStorage.setItem('kice_last_kw', item.kw);
    }

    function showRewardUI(type) {
      const t = document.getElementById('reward-title');
      const m = document.getElementById('reward-msg');
      
      if(type === 'right') {
        const rewardImages = ['images/go1.png', 'images/go2.jpg', 'images/go3.png', 'images/go4.jpg', 'images/go5.jpg'];
        const randomImg = rewardImages[Math.floor(Math.random() * rewardImages.length)];
        document.getElementById('reward-img').src = randomImg;
        
        t.innerText = '🎉 완벽합니다! 최고예요!';
        speakText('화이팅!');
        m.innerHTML = '선생님의 노력은 절대 배신하지 않습니다!<br>이 기세로 2027 합격까지 화이팅! 💖';
        document.querySelector('.modal-content').style.borderColor = '#ec4899';
        
        // Fire confetti
        const duration = 2 * 1000;
        const animationEnd = Date.now() + duration;
        const defaults = { startVelocity: 30, spread: 360, ticks: 60, zIndex: 1001 };
        function randomInRange(min, max) { return Math.random() * (max - min) + min; }
        const interval = setInterval(function() {
          const timeLeft = animationEnd - Date.now();
          if (timeLeft <= 0) { return clearInterval(interval); }
          const particleCount = 50 * (timeLeft / duration);
          confetti(Object.assign({}, defaults, { particleCount, origin: { x: randomInRange(0.1, 0.3), y: Math.random() - 0.2 } }));
          confetti(Object.assign({}, defaults, { particleCount, origin: { x: randomInRange(0.7, 0.9), y: Math.random() - 0.2 } }));
        }, 250);
      } else {
        document.getElementById('reward-img').src = 'images/cheer3.jpg';
        t.innerText = '🐕 괜찮아요! 토닥토닥';
        speakText('힘내세요!');
        m.innerHTML = '틀린 부분은 지금 확실히 잡으면 됩니다!<br>다시 한번 눈도장 찍고 다음으로 넘어가요! 🐾';
        document.querySelector('.modal-content').style.borderColor = '#38bdf8';
      }
      
      modal.style.display = 'flex';
    }

    function closeReward() {
      modal.style.display = 'none';
      goNext();
    }

    
    // --- GOOGLE CLOUD FIREBASE CONFIG & 1-USER 1-DEVICE SYSTEM ---
    const firebaseConfig = {
      apiKey: "AIzaSyBsYj1m_y9IYpo42urauouSqDx38xv6XNE",
      authDomain: "kice-study-29a5c.firebaseapp.com",
      projectId: "kice-study-29a5c",
      storageBucket: "kice-study-29a5c.firebasestorage.app",
      messagingSenderId: "565045000792",
      appId: "1:565045000792:web:840cde0297b7b6bc59a82d"
    };

    // Initialize Firebase
    if (!firebase.apps.length) {
      firebase.initializeApp(firebaseConfig);
    }
    const db = firebase.firestore();

    // Default seed PINs
    const DEFAULT_PINS = {
      "1000": "371400",
      "라이언/재수/경기": "128945",
      "쪼르디/초수/전북": "357281",
      "춘식/초수/경기": "924617",
      "회원1": "825193", "회원2": "491027", "회원3": "637284", "회원4": "159203", "회원5": "748391",
      "회원6": "204958", "회원7": "513842", "회원8": "960175", "회원9": "382469", "회원10": "112233"
    };

    // Generate unique device token for this browser
    let myDeviceId = localStorage.getItem('kice_device_id');
    if (!myDeviceId) {
      myDeviceId = 'dev_' + Math.random().toString(36).substring(2) + Date.now();
      localStorage.setItem('kice_device_id', myDeviceId);
    }

    let unsubscribeSnapshot = null;

    // Listen for concurrent login on other devices in real-time
    function listenToSession(userId) {
      if (unsubscribeSnapshot) unsubscribeSnapshot();
      
      unsubscribeSnapshot = db.collection('users').doc(userId).onSnapshot(doc => {
        if (!doc.exists) return;
        const data = doc.data();
        if (data.activeDeviceId && data.activeDeviceId !== myDeviceId) {
          // Another device logged in! Kick this device out immediately!
          alert('🚨 [동시접속 차단] 다른 기기에서 이 아이디로 로그인하였습니다.\n1인 1계정 원칙에 따라 현재 기기의 접속이 종료됩니다.');
          localStorage.removeItem('kice_auth_id');
          localStorage.removeItem('kice_auth_pin');
          document.getElementById('auth-screen').style.display = 'flex';
        }
      }, err => {
        console.warn('Realtime listener notice:', err);
      });
    }

    async function checkAuth() {
      const savedId = localStorage.getItem('kice_auth_id');
      const savedPin = localStorage.getItem('kice_auth_pin');
      
      if (!savedId || !savedPin) {
        document.getElementById('auth-screen').style.display = 'flex';
        return;
      }
      
      try {
        const docRef = db.collection('users').doc(savedId);
        const doc = await docRef.get();
        
        let validPin = DEFAULT_PINS[savedId];
        if (doc.exists) {
          validPin = doc.data().pin || validPin;
        }
        
        if (savedPin === validPin) {
          document.getElementById('auth-screen').style.display = 'none';
          listenToSession(savedId);
        } else {
          document.getElementById('auth-screen').style.display = 'flex';
        }
      } catch (e) {
        // Fallback if offline
        document.getElementById('auth-screen').style.display = 'none';
      }
    }

    async function submitAuth() {
      const userId = document.getElementById('auth-id').value.trim();
      const pin = document.getElementById('auth-input').value.trim();
      const btn = event?.target;
      const err = document.getElementById('auth-error');
      
      try {
        const docRef = db.collection('users').doc(userId);
        const doc = await docRef.get();
        
        let expectedPin = DEFAULT_PINS[userId];
        if (doc.exists && doc.data().pin) {
          expectedPin = doc.data().pin;
        }
        
        if (pin !== expectedPin) {
          err.innerText = '❌ 암호가 일치하지 않습니다.';
          err.style.display = 'block';
          setTimeout(() => { err.style.display = 'none'; }, 2000);
          return;
        }
        
        // Claim active session on Cloud
        await docRef.set({
          pin: expectedPin,
          activeDeviceId: myDeviceId,
          lastLogin: firebase.firestore.FieldValue.serverTimestamp()
        }, { merge: true });
        
        localStorage.setItem('kice_auth_id', userId);
        localStorage.setItem('kice_auth_pin', pin);
        document.getElementById('auth-screen').style.display = 'none';
        warningCount = 0;
        
        listenToSession(userId);
        alert(userId + '님 환영합니다! (클라우드 1인 1기기 인증 완료)');
      } catch (error) {
        console.error('Auth error:', error);
        alert('서버 인증 중 오류가 발생했습니다: ' + error.message);
      }
    }

    async function changeUserPassword() {
      const currentUser = localStorage.getItem('kice_auth_id');
      if (!currentUser) { alert('먼저 로그인해주세요.'); return; }
      
      const newPwd = prompt("새로운 6자리 암호를 입력하세요:\n(클라우드 서버에 영구 반영되어 모든 기기에 즉시 적용됩니다)");
      if (newPwd && newPwd.length === 6 && /^\d+$/.test(newPwd)) {
        try {
          await db.collection('users').doc(currentUser).set({
            pin: newPwd
          }, { merge: true });
          
          localStorage.setItem('kice_auth_pin', newPwd);
          alert('비밀번호가 [' + newPwd + ']로 클라우드 서버에 안전하게 변경되었습니다!');
        } catch (err) {
          alert('비밀번호 변경 실패: ' + err.message);
        }
      } else if (newPwd) {
        alert("암호는 반드시 6자리 숫자로 입력해주세요.");
      }
    }

    checkAuth();

    // INIT
    renderCard(currentIndex);
    initTable();
    initCanvas();
  
    // Keyboard Shortcuts
    document.addEventListener('keydown', function(e) {
      if (document.getElementById('add-modal') && document.getElementById('add-modal').style.display === 'flex') return;
      if (document.getElementById('reward-modal') && document.getElementById('reward-modal').style.display === 'flex') {
        if (e.key === ' ' || e.key === 'Enter' || e.key === 'ArrowRight' || e.code === 'Space' || e.keyCode === 39 || e.keyCode === 32) {
          e.preventDefault();
          closeReward();
        }
        return;
      }
      if (document.getElementById('mode-anki').style.display === 'none') return;

      const isTyping = ['INPUT', 'TEXTAREA'].includes(document.activeElement.tagName);
      
      const isRight = e.key === 'ArrowRight' || e.code === 'ArrowRight' || e.keyCode === 39;
      const isLeft = e.key === 'ArrowLeft' || e.code === 'ArrowLeft' || e.keyCode === 37;
      const isSpace = e.key === ' ' || e.code === 'Space' || e.keyCode === 32;
      const isEnter = e.key === 'Enter' || e.code === 'Enter' || e.keyCode === 13;
      
      if (isTyping) {
        if (e.key === 'Escape' || e.keyCode === 27) {
          document.activeElement.blur();
        }
        if (e.ctrlKey) {
          if (isSpace || isEnter) {
            e.preventDefault();
            toggleFlip();
          } else if (isRight) {
            e.preventDefault();
            goNext();
          } else if (isLeft) {
            e.preventDefault();
            goPrev();
          }
        }
        return;
      }
      
      if (isSpace || isEnter) {
        e.preventDefault();
        toggleFlip();
      } else if (isRight) {
        e.preventDefault();
        goNext();
      } else if (isLeft) {
        e.preventDefault();
        goPrev();
      }
    });

